<?php
/** Proxy geoespacial de Práctica 06. Las credenciales, si se agregan, viven en PHP. */
function geoFetchJson(string $url): array {
    $ch=curl_init($url);
    curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>25,CURLOPT_USERAGENT=>'BioLab-Observatorio/1.0 (academic project)',CURLOPT_HTTPHEADER=>['Accept: application/json']]);
    $body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);
    if($body===false||$status<200||$status>=300)throw new RuntimeException($error?:"Fuente externa HTTP $status");
    $data=json_decode($body,true);if(!is_array($data))throw new RuntimeException('La fuente devolvió JSON inválido');return $data;
}
function geoCoordinates(): array {
    $lat=$_GET['lat']??null;$lon=$_GET['lon']??null;
    if(!is_numeric($lat)||!is_numeric($lon)){Flight::json(['status'=>'error','message'=>'Envía lat y lon numéricos'],400);return [null,null];}
    $lat=(float)$lat;$lon=(float)$lon;
    if($lat < -90||$lat > 90||$lon < -180||$lon > 180){Flight::json(['status'=>'error','message'=>'Coordenadas fuera del rango válido'],400);return [null,null];}
    return [$lat,$lon];
}
function geoCachedJson(string $key,int $ttl,callable $loader): array {
    $db=null;
    try{$db=Flight::db();$q=$db->prepare('SELECT response_json FROM geo_cache WHERE cache_key=? AND expires_at>NOW()');$q->execute([$key]);$raw=$q->fetchColumn();if($raw!==false){$value=json_decode($raw,true);if(is_array($value))return $value;}}catch(Throwable $ignored){$db=null;}
    $value=$loader();
    if($db){try{$q=$db->prepare('INSERT INTO geo_cache(cache_key,response_json,expires_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE response_json=VALUES(response_json),expires_at=VALUES(expires_at)');$q->execute([$key,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),date('Y-m-d H:i:s',time()+$ttl)]);}catch(Throwable $ignored){}}
    return $value;
}
function geoAverage(array $values): ?float {$values=array_values(array_filter($values,'is_numeric'));return count($values)?array_sum($values)/count($values):null;}
Flight::route('GET /api/geo/clima',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$key=hash('sha256','open-meteo-current:'.round($lat,2).':'.round($lon,2));
    try{$data=geoCachedJson($key,1800,function()use($lat,$lon){$q=http_build_query(['latitude'=>$lat,'longitude'=>$lon,'current'=>'temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m','daily'=>'temperature_2m_mean,precipitation_sum,shortwave_radiation_sum','past_days'=>7,'forecast_days'=>1,'timezone'=>'auto']);$raw=geoFetchJson('https://api.open-meteo.com/v1/forecast?'.$q);$c=$raw['current']??[];$d=$raw['daily']??[];$series=[];foreach(($d['time']??[])as$i=>$date)$series[]=['fecha'=>$date,'temperatura_media_c'=>$d['temperature_2m_mean'][$i]??null,'precipitacion_mm'=>$d['precipitation_sum'][$i]??null,'radiacion_mj_m2_dia'=>$d['shortwave_radiation_sum'][$i]??null];return ['coordenadas'=>['lat'=>$lat,'lon'=>$lon],'fuente'=>'Open-Meteo Forecast API','actual'=>['temperatura_c'=>$c['temperature_2m']??null,'humedad_relativa_pct'=>$c['relative_humidity_2m']??null,'precipitacion_mm'=>$c['precipitation']??null,'viento_kmh'=>$c['wind_speed_10m']??null,'hora'=>$c['time']??null],'serie_diaria'=>$series,'unidades'=>$raw['current_units']??[]];});Flight::json(['status'=>'success','data'=>$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo consultar Open-Meteo: '.$e->getMessage()],502);}
});
Flight::route('GET /api/geo/historico',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$end=date('Y-m-d',strtotime('-7 days'));$start=date('Y-m-d',strtotime($end.' -364 days'));$key=hash('sha256',"open-meteo-history:$lat:$lon:$start:$end");
    try{$data=geoCachedJson($key,86400,function()use($lat,$lon,$start,$end){$q=http_build_query(['latitude'=>$lat,'longitude'=>$lon,'start_date'=>$start,'end_date'=>$end,'daily'=>'temperature_2m_mean,precipitation_sum,shortwave_radiation_sum,et0_fao_evapotranspiration','timezone'=>'auto']);$raw=geoFetchJson('https://archive-api.open-meteo.com/v1/archive?'.$q);$d=$raw['daily']??[];$rain=array_values(array_filter($d['precipitation_sum']??[],'is_numeric'));return ['fuente'=>'Open-Meteo Historical Weather API','periodo'=>['inicio'=>$start,'fin'=>$end],'temperatura_media_c'=>geoAverage($d['temperature_2m_mean']??[]),'precipitacion_total_mm'=>count($rain)?array_sum($rain):null,'radiacion_media_mj_m2_dia'=>geoAverage($d['shortwave_radiation_sum']??[]),'evapotranspiracion_media_mm_dia'=>geoAverage($d['et0_fao_evapotranspiration']??[]),'dias'=>count($d['time']??[])];});Flight::json(['status'=>'success','data'=>['coordenadas'=>['lat'=>$lat,'lon'=>$lon]]+$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo consultar el histórico: '.$e->getMessage()],502);}
});
Flight::route('GET /api/geo/nasa',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$key=hash('sha256','nasa-power:'.round($lat,2).':'.round($lon,2));
    try{$data=geoCachedJson($key,86400,function()use($lat,$lon){$end=date('Ymd',strtotime('-30 days'));$start=date('Ymd',strtotime($end.' -364 days'));$q=http_build_query(['parameters'=>'T2M,PRECTOTCORR,ALLSKY_SFC_SW_DWN','community'=>'AG','longitude'=>$lon,'latitude'=>$lat,'start'=>$start,'end'=>$end,'format'=>'JSON']);$raw=geoFetchJson('https://power.larc.nasa.gov/api/temporal/daily/point?'.$q);$p=$raw['properties']['parameter']??[];$rain=array_values(array_filter($p['PRECTOTCORR']??[],fn($v)=>is_numeric($v)&&(float)$v>-900));return ['fuente'=>'NASA POWER Daily API','periodo'=>['inicio'=>$start,'fin'=>$end],'temperatura_media_c'=>geoAverage(array_values($p['T2M']??[])),'precipitacion_total_mm'=>count($rain)?array_sum(array_map('floatval',$rain)):null,'radiacion_media_mj_m2_dia'=>geoAverage(array_values($p['ALLSKY_SFC_SW_DWN']??[])),'dias'=>count($p['T2M']??[])];});Flight::json(['status'=>'success','data'=>['coordenadas'=>['lat'=>$lat,'lon'=>$lon]]+$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo consultar NASA POWER: '.$e->getMessage()],502);}
});
Flight::route('GET /api/geo/suelo',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$key=hash('sha256','soilgrids-v2:'.round($lat,3).':'.round($lon,3));
    try{$data=geoCachedJson($key,604800,function()use($lat,$lon){$q='lon='.rawurlencode((string)$lon).'&lat='.rawurlencode((string)$lat).'&property=clay&property=sand&property=soc&property=phh2o&depth=0-5cm&value=mean';$raw=geoFetchJson('https://rest.isric.org/soilgrids/v2.0/properties/query?'.$q);$properties=[];foreach(($raw['properties']['layers']??[])as$layer){$name=$layer['name']??'';$properties[$name]=['valor'=>$layer['depths'][0]['values']['mean']??null,'unidad'=>$layer['unit_measure']['mapped_units']??$layer['unit_measure']['target_units']??null];}return ['coordenadas'=>['lat'=>$lat,'lon'=>$lon],'fuente'=>'ISRIC SoilGrids v2.0','profundidad'=>'0-5 cm','propiedades'=>$properties,'atribucion'=>'ISRIC SoilGrids'];});Flight::json(['status'=>'success','data'=>$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo consultar SoilGrids: '.$e->getMessage()],502);}
});
Flight::route('GET /api/geo/ocurrencias',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$name=trim((string)($_GET['especie']??''));if($name===''){Flight::json(['status'=>'error','message'=>'Envía el nombre científico en especie'],400);return;}$limit=max(1,min(300,(int)($_GET['limit']??150)));$key=hash('sha256','gbif:'.strtolower($name).':'.round($lat,1).':'.round($lon,1).':'.$limit);
    try{$data=geoCachedJson($key,86400,function()use($name,$lat,$lon,$limit){$match=geoFetchJson('https://api.gbif.org/v1/species/match?'.http_build_query(['name'=>$name]));$taxon=$match['usageKey']??$match['speciesKey']??null;if(!$taxon)return ['fuente'=>'GBIF Occurrence API','nombre_consultado'=>$name,'coincidencia'=>$match,'total'=>0,'puntos'=>[]];$delta=.5;$query=http_build_query(['taxonKey'=>$taxon,'decimalLatitude'=>max(-90,$lat-$delta).','.min(90,$lat+$delta),'decimalLongitude'=>max(-180,$lon-$delta).','.min(180,$lon+$delta),'hasCoordinate'=>'true','limit'=>$limit,'offset'=>0]);$raw=geoFetchJson('https://api.gbif.org/v1/occurrence/search?'.$query);$points=[];foreach(($raw['results']??[])as$r)if(isset($r['decimalLatitude'],$r['decimalLongitude']))$points[]=['lat'=>(float)$r['decimalLatitude'],'lon'=>(float)$r['decimalLongitude'],'fecha'=>$r['eventDate']??null,'pais'=>$r['country']??null];return ['fuente'=>'GBIF Occurrence API','nombre_consultado'=>$name,'nombre_aceptado'=>$match['scientificName']??$name,'taxonKey'=>$taxon,'radio_grados'=>$delta,'total'=>(int)($raw['count']??0),'puntos'=>$points,'limite_mostrado'=>$limit];});Flight::json(['status'=>'success','data'=>$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudieron consultar ocurrencias GBIF: '.$e->getMessage()],502);}
});
Flight::route('GET /api/geo/lugar',function(){
    [$lat,$lon]=geoCoordinates();if($lat===null)return;$key=hash('sha256','nominatim-reverse:'.round($lat,3).':'.round($lon,3));
    try{$data=geoCachedJson($key,2592000,function()use($lat,$lon){$q=http_build_query(['format'=>'jsonv2','lat'=>$lat,'lon'=>$lon,'zoom'=>10,'addressdetails'=>1]);$raw=geoFetchJson('https://nominatim.openstreetmap.org/reverse?'.$q);$a=$raw['address']??[];return ['fuente'=>'OpenStreetMap Nominatim','nombre'=>$raw['name']??$a['city']??$a['town']??$a['village']??$a['county']??$raw['display_name']??null,'pais'=>$a['country']??null,'display_name'=>$raw['display_name']??null,'atribucion'=>'© OpenStreetMap contributors'];});Flight::json(['status'=>'success','data'=>$data]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo identificar el lugar: '.$e->getMessage()],502);}
});
function geoSuitability(array $climate,array $soil,int $gbif): array {
    $temp=(float)($climate['temperatura_media_c']??25);$rain=(float)($climate['precipitacion_total_mm']??0);$raw=$soil['propiedades']['phh2o']['valor']??null;$ph=is_numeric($raw)?(float)$raw/10:null;
    $parts=['temperatura'=>max(0,min(100,100-abs($temp-25)*4)),'precipitacion'=>$rain>=400?100:max(0,$rain/4),'suelo_ph'=>$ph===null?50:max(0,min(100,100-abs($ph-6.5)*25)),'evidencia_gbif'=>$gbif>0?100:35];
    $score=(int)round($parts['temperatura']*.30+$parts['precipitacion']*.25+$parts['suelo_ph']*.25+$parts['evidencia_gbif']*.20);$advice=[];
    if($rain<400)$advice[]=['prioridad'=>'crítica','mensaje'=>'Precipitación anual inferior a 400 mm: se recomienda riego suplementario.'];
    if($temp>35)$advice[]=['prioridad'=>'alta','mensaje'=>'Temperatura media superior a 35 °C: considerar una variedad resistente al calor.'];
    if($gbif===0)$advice[]=['prioridad'=>'alta','mensaje'=>'No hay ocurrencias GBIF cercanas para esta especie; la adaptación local tiene mayor incertidumbre.'];
    if($ph!==null&&$ph<5.5)$advice[]=['prioridad'=>'media','mensaje'=>'Suelo ácido (pH menor a 5.5): evaluar encalado antes de sembrar.'];
    $radiation=$climate['radiacion_media_mj_m2_dia']??null;if(is_numeric($radiation)&&$radiation>25)$advice[]=['prioridad'=>'media','mensaje'=>'Radiación superior a 25 MJ/m²/día: evaluar sombra parcial.'];
    if(!$advice)$advice[]=['prioridad'=>'baja','mensaje'=>'Sin alertas por los umbrales básicos; valida la decisión con datos de parcela.'];
    return ['indice_idoneidad'=>$score,'componentes'=>$parts,'pesos'=>['temperatura'=>.30,'precipitacion'=>.25,'suelo_ph'=>.25,'evidencia_gbif'=>.20],'recomendaciones'=>$advice];
}
Flight::route('POST /api/geo/analisis',function(){
    $d=json_decode(Flight::request()->getBody(),true)??[];$lat=$d['lat']??null;$lon=$d['lon']??null;
    if(!is_numeric($lat)||!is_numeric($lon)||(float)$lat < -90||(float)$lat > 90||(float)$lon < -180||(float)$lon > 180){Flight::json(['status'=>'error','message'=>'Coordenadas lat/lon inválidas'],400);return;}
    try{$climate=is_array($d['clima']??null)?$d['clima']:[];$soil=is_array($d['suelo']??null)?$d['suelo']:[];$gbif=max(0,(int)($d['ocurrencias_gbif']??0));$fit=geoSuitability($climate,$soil,$gbif);$db=Flight::db();$q=$db->prepare('INSERT INTO geo_analisis(lat,lon,nombre_lugar,especie_id,clima_json,suelo_json,ocurrencias_gbif,indice_idoneidad,recomendaciones_json,simulacion_id) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([(float)$lat,(float)$lon,substr((string)($d['nombre_lugar']??''),0,180),!empty($d['especie_id'])?(int)$d['especie_id']:null,json_encode($climate,JSON_UNESCAPED_UNICODE),json_encode($soil,JSON_UNESCAPED_UNICODE),$gbif,$fit['indice_idoneidad'],json_encode($fit['recomendaciones'],JSON_UNESCAPED_UNICODE),!empty($d['simulacion_id'])?(int)$d['simulacion_id']:null]);Flight::json(['status'=>'success','data'=>['id'=>(int)$db->lastInsertId()]+$fit],201);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo guardar el análisis: '.$e->getMessage()],500);}
});
Flight::route('PUT /api/geo/analisis/@id/simulacion',function($id){$d=json_decode(Flight::request()->getBody(),true)??[];$sim=(int)($d['simulacion_id']??0);if($sim<1){Flight::json(['status'=>'error','message'=>'simulacion_id requerido'],400);return;}try{$db=Flight::db();$q=$db->prepare('UPDATE geo_analisis SET simulacion_id=? WHERE id=?');$q->execute([$sim,(int)$id]);Flight::json(['status'=>'success','message'=>'Análisis geográfico asociado a la simulación']);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo asociar la simulación: '.$e->getMessage()],500);}});
Flight::route('GET /api/geo/ubicaciones',function(){try{$rows=Flight::db()->query('SELECT id,nombre,pais,lat,lon,descripcion FROM geo_sites ORDER BY nombre')->fetchAll();Flight::json(['status'=>'success','data'=>$rows]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudieron cargar las ubicaciones: '.$e->getMessage()],500);}});
Flight::route('GET /api/geo/ranking',function(){try{$db=Flight::db();$rows=$db->query('SELECT g.id,g.lat,g.lon,g.nombre_lugar,g.especie_id,e.nombre_comun AS especie,g.ocurrencias_gbif,g.indice_idoneidad,g.created_at FROM geo_analisis g LEFT JOIN especies e ON e.id=g.especie_id ORDER BY g.indice_idoneidad DESC,g.created_at DESC LIMIT 100')->fetchAll();Flight::json(['status'=>'success','data'=>$rows]);}catch(Throwable $e){Flight::json(['status'=>'error','message'=>'No se pudo cargar el ranking: '.$e->getMessage()],500);}});